            canonical_function_signature(alias),
            canonical_function_signature(explicit),
        )
        self.assertEqual(
            function_selector(alias), function_selector(explicit)
        )

    def test_calldata_roundtrip_and_canonical_arg_types(self):
        abi = self._alias_abi()
        args = [
            2 ** 256 - 1,
