            Decimal("2.25"),
            ([1, 2], [b"a", b"b"]),
        ]
        encoded = encode_function_call(abi, "f", args)
        decoded = decode_function_call(abi, encoded.calldata)
        self.assertEqual(decoded.values, tuple(args))
        self.assertEqual(
            [arg.type for arg in decoded.args],
